// Quest 3 — tile-based pixel art world with shared sprite/physics layout.
// All world positions use the 1456×1088 coordinate system. Solid shapes are built
// from the same source that authored the storefronts and furniture sprites.
// The two doors are the only exit portals in the Phaser scene.

import layout from '../../../assets/cc/pixel-world/layout.json' with { type: 'json' }
import { createGrid, toRows } from './grid.mjs'

const TILE = 16
const WIDTH = 91
const HEIGHT = 68

// Uses the inside face of the wall generated by the artwork authoring tool.
const boundary = layout.walkablePolygon

function isInside(x, y) {
  // The north exit continues beyond the building, and the south entry has an
  // accessible threshold. Exits are handled by E in the scene, not crossing void.
  if (x > 642 && x < 780 && y < 106) return true
  if (x > 628 && x < 796 && y > 888 && y < 990) return true
  let included = false
  for (let i = 0, j = boundary.length - 1; i < boundary.length; j = i++) {
    const [ax, ay] = boundary[i]
    const [bx, by] = boundary[j]
    if (ay > y !== by > y && x < ((bx - ax) * (y - ay)) / (by - ay) + ax) {
      included = !included
    }
  }
  return included
}

const floor = createGrid(WIDTH, HEIGHT, ' ')
for (let y = 0; y < HEIGHT; y++) {
  for (let x = 0; x < WIDTH; x++) {
    const px = x * TILE + TILE / 2
    const py = y * TILE + TILE / 2
    if (isInside(px, py)) {
      floor[y][x] = px > 626 && px < 814 && py > 720 ? '#' : '.'
    }
  }
}

// Rendered sprite silhouettes may be tall, but their actual *ground contact*
// rectangles are deliberately small. This is what makes a character pass behind
// a counter canopy while still colliding with the counter legs/cabinet.
const solids = layout.props.flatMap((prop) => {
  const [dx, dy, width, height] = prop.solid
  if (width < 1 || height < 1) return []
  return [
    {
      id: prop.id,
      label: prop.label ?? prop.id,
      kind:
        prop.kind === 'center' || prop.kind === 'table' || prop.kind === 'planter'
          ? 'ellipse'
          : 'rect',
      x: prop.x + dx,
      y: prop.y + dy,
      width,
      height,
      color: '#52617c',
    },
  ]
})

/** @type {import('@unifor-quest/campus').MapDescription} */
export const centroDeConvivenciaDescription = {
  id: 'centro-de-convivencia',
  tileset: 'indoor',
  width: WIDTH,
  height: HEIGHT,
  terrain: toRows(floor),
  buildings: [],
  shapes: solids,
}
